const D = { scale:1, energy:.7, hue:190, speed:1, density:.5, x:.5, y:.82, pose:'cycle', style:'candy', act:'showoff', stance:.5, chop:.4, chrome:.6, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const md = (a,n)=>((a%n)+n)%n;
const frc = v=>v-Math.floor(v);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const ez = t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr = i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u = Math.min(width,height);
const sc = u*P.scale/320;
const bt = K.beat*P.speed;
const sub = frc(bt);
const pop = K.pulse;
const kick = pop*.6 + A.bass*.85;
const H = md(P.hue,360);
const style = P.style;
const candy=style==='candy', primer=style==='primer', flake=style==='flake', chrome=style==='chrome', blue=style==='blueprint';
const en = P.energy*(.5+.6*K.intensity);

// geometry morphs
const halfBase = 92;                 // axle half-spacing
const bodyW = 138;                   // body half-width
const rimR = 34 + P.stance*6;        // wheel radius
const roofDrop = 1 - P.chop*.55;     // chopped-top factor

// ---- seed-keyed flake / detail layout ----
if (S.seedUsed!==P.seed) {
  S.seedUsed=P.seed;
  S.flk=[];
  for (let i=0;i<70;i++) S.flk.push({x:(fr(i*2+1)-.5)*250, y:-(20+fr(i*2+2)*70), ph:fr(i*3+5)*6.28, s:1.1+fr(i*4+7)*2.2});
  S.tape=[];
  for (let i=0;i<9;i++) S.tape.push({dh:(fr(i*5+3)-.5)*70, r:120+fr(i*5+4)*70, a:fr(i*5+6)*6.28});
}

// ---- hop rig (all from clk) ----
const amp = 44*en*(P.act==='cruise'?.45:1);
const load = sub>.7 ? (sub-.7)/.3 : 0;
let mv = P.pose;
if (mv==='cycle') {
  const ph = md(bt,16);
  if (P.act==='cruise') { mv = ph<12?'cruise':'side'; }
  else { mv = ph<4?'front':ph<8?'back':ph<12?'side':(K.section%4===3?'pancake':'front'); }
}
let fLift=0, bLift=0, wheelJmp=0, freeze=0;
const beatIdx = Math.floor(md(bt,2));
if (mv==='front') { fLift = pop*amp - load*amp*.35; bLift = pop*amp*.12; }
else if (mv==='back') { bLift = pop*amp; fLift = pop*amp*.12 - load*amp*.2; }
else if (mv==='side') { if(beatIdx===0){fLift=pop*amp;bLift=pop*amp*.1;} else {bLift=pop*amp;fLift=pop*amp*.1;} }
else if (mv==='pancake') { const j=pop; fLift=j*amp*1.15; bLift=j*amp*1.15; wheelJmp=j*amp*.32; freeze=Math.max(0,K.swell-.5); }
else { const s=Math.sin(bt*Math.PI); fLift=(K.swell*.4+ .5+.5*s)*amp*.3; bLift=(K.swell*.4+.5-.5*s)*amp*.3; }
// showoff act: hold a 3-wheel freeze on section boundary
if (P.act==='showoff' && K.section%4===2) { const hold=ez((md(bt,4))/1.2); bLift=Math.max(bLift, amp*1.1*(1-hold*.2)); }

const bodyLift = (fLift+bLift)/2;
const pitch = (fLift-bLift)*.0042;   // nose-up positive
const gy = -rimR - wheelJmp;         // wheel center y (ground contact at 0)

// ---- style fills ----
function bodyBase(){
  if (blue){ noFill(); return; }
  if (primer){ fill(H, 8, 52); return; }
  if (chrome){ fill(210, 6, 62); return; }
  fill(H, candy?78:70, candy?70:74);
}
function bodyLine(w){
  if (blue){ stroke(205,60,100,90); strokeWeight(w*.7); return; }
  if (chrome){ stroke(210,10,20,80); strokeWeight(w); return; }
  if (primer){ stroke(H,10,30,70); strokeWeight(w); return; }
  stroke(H,90,16,95); strokeWeight(w);
}

// ---- spoke wheel ----
function wheel(cx){
  push(); translate(cx, gy);
  // tire (whitewall) unless blueprint
  if (blue){
    stroke(205,55,100,85); strokeWeight(1.6); noFill();
    ellipse(0,0,rimR*2,rimR*2); ellipse(0,0,rimR*1.15,rimR*1.15);
    // dimension cross
    line(-rimR,0,rimR,0); line(0,-rimR,0,rimR);
  } else {
    noStroke(); fill(0,0,primer?7:9); ellipse(0,0,rimR*2.05,rimR*2.05);
    fill(0,0,96); ellipse(0,0,rimR*1.62,rimR*1.62);      // whitewall
    fill(0,0,primer?10:6); ellipse(0,0,rimR*1.34,rimR*1.34);
  }
  // dayton wire spokes (chrome) — rotate slowly with travel
  const rot = K.beat*.6*P.speed;
  push(); rotate(rot);
  const nsp = blue?8:16;
  for (let i=0;i<nsp;i++){
    const a=i/nsp*6.2832;
    if (blue){ stroke(205,50,100,55); strokeWeight(.8); }
    else { stroke(0,0, i%2?70:96, 90); strokeWeight(1.4); }
    line(0,0, Math.cos(a)*rimR*1.18, Math.sin(a)*rimR*1.18);
  }
  pop();
  // chrome knock-off hub
  if (!blue){ noStroke(); fill(0,0,88); ellipse(0,0,rimR*.5,rimR*.5); fill(0,0,100,80); ellipse(-rimR*.1,-rimR*.1,rimR*.2,rimR*.2); }
  else { noFill(); stroke(205,55,100,80); strokeWeight(1.2); ellipse(0,0,rimR*.5,rimR*.5); }
  pop();
}

// ---- render ----
push();
translate(P.x*width + Math.sin(K.t*.16)*10*sc, P.y*height);
scale(sc);

// undercarriage neon glow (density-gated, ADD)
if (!blue && P.density>.02){
  blendMode(ADD);
  const gl = clp(10 + kick*20 + K.swell*8, 0, 40)*P.density;
  noStroke(); fill(md(H+140,360),85,100, gl);
  ellipse(0, -6 + bodyLift*.2, (bodyW+40)*1.9, 46);
  blendMode(BLEND);
}

// floor shadow (tightens as car lifts)
noStroke(); fill(0,0,0, clp(40 - bodyLift*.4,10,44));
ellipse(0, 2, (bodyW+34)*2*(1 - bodyLift*.0016), 20);

// wheels (behind body)
wheel(-halfBase);
wheel(halfBase);

// hydraulic pistons (extend when body lifts)
if (!blue){
  stroke(0,0,82,80); strokeWeight(4);
  line(-halfBase, gy, -halfBase, gy - (18+fLift*.9));
  line(halfBase, gy, halfBase, gy - (18+bLift*.9));
  stroke(0,0,55,70); strokeWeight(6);
  line(-halfBase, gy-6, -halfBase, gy-6-(8+fLift*.5));
  line(halfBase, gy-6, halfBase, gy-6-(8+bLift*.5));
}

// ===== BODY GROUP =====
push();
translate(0, -rimR - 30 - bodyLift);
rotate(-pitch);

// lower body silhouette
bodyLine(3.2); bodyBase();
beginShape();
vertex(-bodyW, 6); vertex(-bodyW-6, -14); vertex(-bodyW+6,-30);
vertex(-70,-34); vertex(-56,-58*roofDrop);              // cowl to windshield
vertex(-8,-70*roofDrop); vertex(46,-70*roofDrop);       // roof
vertex(74,-40); vertex(bodyW-4,-32);                    // rear deck
vertex(bodyW+6,-14); vertex(bodyW,6);
endShape(CLOSE);

// wheel arches (cutouts as dark arcs)
if (!blue){ noStroke(); fill(0,0,primer?8:6);
  arc(-halfBase, 6+ (rimR+30+bodyLift)-4, rimR*2.1, rimR*2.1, Math.PI, 6.2832);
  arc(halfBase, 6+ (rimR+30+bodyLift)-4, rimR*2.1, rimR*2.1, Math.PI, 6.2832);
}

// greenhouse / windows
if (blue){
  stroke(205,55,100,80); strokeWeight(1); noFill();
  beginShape(); vertex(-52,-56*roofDrop); vertex(-10,-66*roofDrop); vertex(42,-66*roofDrop); vertex(66,-40); endShape();
} else {
  noStroke(); fill(200,45,chrome?40:22, 92);
  beginShape(); vertex(-50,-54*roofDrop); vertex(-10,-64*roofDrop); vertex(40,-64*roofDrop); vertex(62,-40); vertex(-46,-40); endShape(CLOSE);
  // window reflection streak
  fill(200,10,90,26);
  quad(-30,-56*roofDrop,-14,-58*roofDrop,-2,-42,-18,-42);
  // chrome pillar + trim
  stroke(0,0,92,90); strokeWeight(2); noFill();
  line(-6,-64*roofDrop,-6,-40); line(-46,-42, 62,-40);
}

// candy sheen: airbrushed tonal bands (translucent overlays)
if (candy||flake){
  noStroke();
  fill(H,45,100,26); quad(-bodyW,-6,bodyW,-14,bodyW,-26,-bodyW,-16);   // upper light band
  fill(H,95,34,34); quad(-bodyW,6,bodyW,6,bodyW,-6,-bodyW,-4);          // lower dark band
  // moving specular glint sweep
  const gx = -bodyW + md(K.t*40, bodyW*2.4);
  fill(0,0,100, 30 + kick*30);
  quad(gx-6,-30, gx+10,-30, gx+2,8, gx-14,8);
}
if (chrome){
  noStroke();
  for (let b=0;b<6;b++){ const yy=-32+b*7; fill(210,8, b%2?90:30, 40); rect(-bodyW,yy,bodyW*2,6); }
  const gx = -bodyW + md(K.t*60, bodyW*2.4);
  fill(0,0,100,55); rect(gx-3,-34,7,42);
}
if (primer){
  // masking tape + bondo spots (matte, austere)
  noStroke(); fill(H,4,72,60); rect(-40,-40,26,50); rect(30,-30,20,34);
  fill(H,14,40,40); ellipse(-10,-20,20,14); ellipse(70,-16,16,10);
  stroke(H,6,80,50); strokeWeight(1); line(-40,-40,-40,10); line(50,-30,50,4);
}

// pinstripe accent (candy/flake)
if (candy||flake){
  stroke(md(H+150,360),85,100,90); strokeWeight(1.6); noFill();
  beginShape(); vertex(-bodyW+10,-8); bezierVertex(-40,-2,40,-16,bodyW-14,-10); endShape();
  stroke(md(H+30,360),90,100,70); strokeWeight(1);
  beginShape(); vertex(-bodyW+12,-4); bezierVertex(-30,2,50,-12,bodyW-16,-6); endShape();
}

// door split line
if (!blue){ stroke(0,0,primer?20:12, 70); strokeWeight(1.4); line(2,-40,6,4); }
else { stroke(205,50,100,50); strokeWeight(.8); line(2,-40,6,4);
  // blueprint dimension ticks
  stroke(205,60,100,70); strokeWeight(.8);
  line(-bodyW,20,bodyW,20); line(-bodyW,16,-bodyW,24); line(bodyW,16,bodyW,24);
}

// chrome bumpers + grille
if (!blue){
  noStroke();
  const chm = clp(.4+P.chrome*.6,0,1);
  fill(0,0, chrome?70:82); rect(-bodyW-8,-16,10,20,3); rect(bodyW-2,-16,10,20,3);   // bumpers
  fill(0,0,100, 60*chm); rect(-bodyW-8,-16,10,5,2); rect(bodyW-2,-16,10,5,2);       // bumper glint
  // grille slats
  stroke(0,0,88,80); strokeWeight(1.2);
  for (let i=0;i<5;i++) line(-bodyW-2,-12+i*4,-bodyW-8,-12+i*4);
  // headlight
  noStroke(); fill(48,30,100, 80+kick*15); ellipse(-bodyW+2,-20,8,8);
  fill(0,80,90,80); ellipse(bodyW-2,-18,6,6);
}

// flake sparkle
if (flake){
  blendMode(ADD); noStroke();
  for (let i=0;i<70;i++){ const f=S.flk[i];
    const tw=(Math.sin(K.t*2.2+f.ph)*.5+.5);
    fill(md(H+30,360),20,100, tw*(28+A.treble*50));
    ellipse(f.x*.5, f.y*.5, f.s, f.s);
  }
  blendMode(BLEND);
}

pop(); // end body group

// hop spark accents at each corner on the pop (candy/flake)
if ((candy||flake||chrome) && pop>.25){
  blendMode(ADD); noStroke();
  const spk=pop*(.6+en);
  fill(0,0,100, 40*spk);
  ellipse(-halfBase, gy - (18+fLift), 30*spk, 8*spk);
  ellipse(halfBase, gy - (18+bLift), 30*spk, 8*spk);
  blendMode(BLEND);
}
pop();
